import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-PPROPERTIES.md","filePath":"manual-en/CTABLES-PPROPERTIES.md","lastUpdated":1785684581000}'),r={name:"manual-en/CTABLES-PPROPERTIES.md"};function p(c,e,d,i,n,m){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h4 id="_15-7-10-2-pproperties" tabindex="-1">15.7.10.2 PPROPERTIES <a class="header-anchor" href="#_15-7-10-2-pproperties" aria-label="Permalink to &quot;15.7.10.2 PPROPERTIES&quot;">​</a></h4><pre><code>/PPROPERTIES &amp;_postcompute_ …
    [LABEL=_string_]
    [FORMAT=[_summary_ _format_]…]
    [HIDESOURCECATS={NO _|_ YES}
</code></pre><p>The <code>PPROPERTIES</code> subcommand, which must appear before <code>TABLE</code>, sets properties for one or more postcomputes defined on prior <code>PCOMPUTE</code> subcommands. The subcommand syntax begins with the list of postcomputes, each prefixed with ‘&amp;’ as specified on <code>PCOMPUTE</code>.</p><p>All of the settings on <code>PPROPERTIES</code> are optional. Use <code>LABEL</code> to set the label shown for the postcomputes in table output. The default label for a postcompute is the expression used to define it.</p><p>A postcompute always uses same summary functions as the variable whose categories contain it, but <code>FORMAT</code> allows control over the format used to display their values. It takes a list of summary function names and format specifiers.</p><p>By default, or with <code>HIDESOURCECATS=NO</code>, categories referred to by computed categories are displayed like other categories. Use <code>HIDESOURCECATS=YES</code> to hide them.</p><p>The previous section provides an example for <code>PPROPERTIES</code>.</p>`,7)])])}const P=o(r,[["render",p]]);export{E as __pageData,P as default};
